# A-B 이원계: 조성 x(B 비율)와 형성 엔탈피(eV/원자)로 볼록 껍질과 '껍질 위 에너지'를 구한다
pts = {"A": (0.0, 0.0), "B": (1.0, 0.0), "AB": (0.5, -0.40),
       "A3B": (0.25, -0.15), "AB3": (0.75, -0.25)}
def hull(points):                       # 아래쪽 볼록 껍질 (모노톤 체인)
    P = sorted(points); H = []
    for p in P:
        while len(H) >= 2 and ((H[-1][0]-H[-2][0])*(p[1]-H[-2][1])
                               - (H[-1][1]-H[-2][1])*(p[0]-H[-2][0])) <= 0:
            H.pop()
        H.append(p)
    return H
def e_hull(x, H):                       # x 에서 껍질 높이(선형 보간)
    for (x1, y1), (x2, y2) in zip(H, H[1:]):
        if x1 <= x <= x2:
            return y1 + (y2-y1)*(x-x1)/(x2-x1)
H = hull(list(pts.values()))
for name, (x, e) in pts.items():
    print(f"{name:4s} x={x:.2f} E_f={e:+.2f}  E_above_hull={e - e_hull(x, H):.3f}")
